import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

_TIMESTAMP_HEADER = "X-Pay-Timestamp"
_SIGNATURE_HEADER = "X-Pay-Signature"
_SIGNATURE_SCHEME = "v1="
_MAX_CLOCK_SKEW_SECONDS = 300
_DIGEST_HEX_LENGTH = 64

_TIMESTAMP_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")
_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{%d}" % _DIGEST_HEX_LENGTH)
_CURRENCY_PATTERN = re.compile(r"[A-Z]{3}")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    body = _body_bytes(raw_body)
    timestamp = _header(headers, _TIMESTAMP_HEADER)
    signature = _header(headers, _SIGNATURE_HEADER)
    seconds = _timestamp_seconds(timestamp)
    _verify_digest(body, timestamp, signature, secret)
    _verify_recency(seconds, now)
    event = _json_object(body)
    return {
        "event_id": _text(event, "event_id"),
        "account_id": _text(event, "account_id"),
        "amount_minor": _amount(event),
        "currency": _currency(event),
    }


def _body_bytes(raw_body):
    if isinstance(raw_body, str):
        return raw_body.encode("utf-8")
    if isinstance(raw_body, (bytes, bytearray, memoryview)):
        return bytes(raw_body)
    raise InvalidNotification("notification body must be request bytes")


def _header(headers, name):
    try:
        pairs = headers.items()
    except AttributeError:
        pairs = headers
    wanted = name.lower()
    for key, value in pairs or ():
        if isinstance(key, str) and key.lower() == wanted and value is not None:
            return value.strip() if isinstance(value, str) else value
    return None


def _timestamp_seconds(timestamp):
    if not isinstance(timestamp, str) or not _TIMESTAMP_PATTERN.fullmatch(timestamp):
        raise InvalidNotification("missing or malformed X-Pay-Timestamp header")
    return float(timestamp)


def _verify_recency(seconds, now):
    if abs(seconds - now) > _MAX_CLOCK_SKEW_SECONDS:
        raise InvalidNotification("delivery timestamp is outside the accepted window")


def _verify_digest(body, timestamp, signature, secret):
    if not isinstance(signature, str):
        raise InvalidNotification("missing X-Pay-Signature header")
    scheme = signature[:len(_SIGNATURE_SCHEME)]
    digest = signature[len(_SIGNATURE_SCHEME):]
    if scheme.lower() != _SIGNATURE_SCHEME or not _DIGEST_PATTERN.fullmatch(digest):
        raise InvalidNotification("malformed or unsupported X-Pay-Signature header")
    expected = hmac.new(_secret_bytes(secret), _signed_bytes(timestamp, body),
                        hashlib.sha256).digest()
    if not hmac.compare_digest(expected, bytes.fromhex(digest)):
        raise InvalidNotification("v1 signature does not match the received body")


def _signed_bytes(timestamp, body):
    return timestamp.encode("ascii") + b"." + body


def _secret_bytes(secret):
    if isinstance(secret, str):
        key = secret.encode("utf-8")
    elif isinstance(secret, (bytes, bytearray, memoryview)):
        key = bytes(secret)
    else:
        raise InvalidNotification("provider secret must be bytes")
    if not key:
        raise InvalidNotification("provider secret is not configured")
    return key


def _json_object(body):
    try:
        event = json.loads(body)
    except (ValueError, RecursionError) as exc:
        raise InvalidNotification("notification body is not valid JSON") from exc
    if not isinstance(event, dict):
        raise InvalidNotification("notification body must be a JSON object")
    return event


def _text(event, field):
    value = event.get(field)
    if not isinstance(value, str) or not value:
        raise InvalidNotification("%s must be a nonempty string" % field)
    return value


def _amount(event):
    value = event.get("amount_minor")
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise InvalidNotification("amount_minor must be a nonnegative integer")
    return value


def _currency(event):
    value = event.get("currency")
    if not isinstance(value, str) or not _CURRENCY_PATTERN.fullmatch(value):
        raise InvalidNotification("currency must be three uppercase ASCII letters")
    return value
